INSERT INTO items (item_type_id, content, answer_set, word_count, difficulty, cefr_level, status, pool, topic, exam_part_id, exam_order) VALUES
('story_retelling', '{"story": "David had been saving money for a new bicycle for several months. Last weekend, he finally visited the shop downtown and found the exact model he wanted. The salesperson offered him a small discount because it was the last one in stock. David happily paid and rode it home that same afternoon."}'::jsonb, null, 56, 0.52, 'B1', 'approved', 'exam', 'shopping', 'e5000000-0000-4000-8000-000000000015', 1),
('story_retelling', '{"story": "A small startup was struggling to attract investors. The founder revised the pitch to focus on real customer testimonials instead of only financial projections. The new approach resonated much more with potential investors. Within a month, the startup secured its first major round of funding."}'::jsonb, null, 46, 0.55, 'B2', 'approved', 'exam', 'business', 'e5000000-0000-4000-8000-000000000015', 2),
('story_retelling', '{"story": "An employee noticed that a long-standing process was wasting significant time every week. Instead of simply complaining, she proposed a simpler alternative to her manager. The manager tested the new process for a month. It saved the team several hours a week, and it was adopted company-wide."}'::jsonb, null, 48, 0.54, 'B2', 'approved', 'exam', 'business', 'e5000000-0000-4000-8000-000000000015', 3);
